&lt;li style=&quot;font-size: 12pt;&quot;&gt;
&lt;p data-renderer-start-pos=&quot;5914&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Hands-on experience integrating with Japan market infrastructure such as &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;JPX&lt;/span&gt; (&lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;TSE&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;/&lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;OSE&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;), &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;JSCC&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;JASDEC&lt;/span&gt;, or major Japanese banks.&lt;/span&gt;&lt;/p&gt;
